import * as z from 'zod'

/**
 * Validates a string that contains only digits (non-negative integer).
 */
export const STRING_INT = z.string().regex(/^\d+$/)

/**
 * Validates a string that represents a decimal number.
 */
export const STRING_DECIMAL = z.string().regex(/^\d*\.\d+$/)

/**
 * Validates a URL string using Zod's built-in URL validation.
 */
export const URL = z.url()

/**
 * Validates a 64-character hexadecimal string (e.g., block hash, public key).
 */
export const HEX_64 = z
  .string()
  .length(64)
  .regex(/^[0-9A-F]{64}$/i)

/**
 * Validates a Nano Proof-of-Work value (hexadecimal string).
 */
export const NANO_WORK = z.string().regex(/^[0-9A-F]+$/i)

/**
 * Validates a Nano account address (supports both 'nano_' and 'xrb_' prefixes).
 */
export const NANO_ACCOUNT = z.string().regex(/^(nano_|xrb_)[13][1-9a-km-uw-z]{59}$/)

/**
 * Schema for successful account information response from Nano node.
 */
export const ACCOUNT_INFO_SUCCESS = z.object({
  frontier: HEX_64,
  open_block: HEX_64,
  representative_block: HEX_64,
  representative: NANO_ACCOUNT,
  balance: STRING_INT,
  modified_timestamp: STRING_INT,
  block_count: STRING_INT,
  account_version: STRING_INT.optional(),
  confirmation_height: STRING_INT,
  confirmation_height_frontier: HEX_64,
})

/**
 * Configuration schema for the x402 Nano Helper class.
 */
export const HELPER_CONFIG = z.object({
  NANO_RPC_URL: URL.optional(),
  NANO_WORK_GENERATION_URL: URL.optional(),
  NANO_ACCOUNT_PRIVATE_KEY: HEX_64.optional(),
})

/**
 * Schema for successful Nano block processing response.
 */
export const PROCESS_BLOCK_SUCCESS = z.object({
  hash: HEX_64,
})

/**
 * Schema for Nano RPC error response.
 */
export const NANO_RPC_ERROR = z.object({
  error: z.string(),
})

/**
 * Schema for a Nano send block (state block type).
 */
export const NANO_SEND_BLOCK = z.strictObject({
  type: z.literal('state'),
  account: NANO_ACCOUNT,
  previous: HEX_64,
  representative: NANO_ACCOUNT,
  balance: STRING_INT,
  link: HEX_64,
  link_as_account: NANO_ACCOUNT.optional(),
  work: z.string().regex(/^[0-9A-F]+$/i),
  signature: z.string().regex(/^[0-9A-F]{128}$/i),
})

/**
 * Schema for Nano RPC work generation response.
 */
export const NANO_RPC_CALL_WORK_GENERATE_RESPONSE = z.object({
  work: NANO_WORK,
  difficulty: z.string(),
  multiplier: z.string(),
  hash: HEX_64,
})

/**
 * Schema for Exact Nano payment payload.
 */
export const EXACT_NANO_PAYLOAD = z.object({
  block: NANO_SEND_BLOCK,
})

/**
 * Schema for AssetAmount with asset code, amount, and optional extra metadata.
 */
export const ASSET_AMOUNT = z.object({
  asset: z.string(),
  amount: z.string(),
  extra: z.object().optional(),
})

/**
 * Schema for function passed to custom work generator.
 */
export const WORK_GENERATOR = z.function({
  input: [z.string()],
  output: z.string(),
})
